import{_ as e,o as d,c as o,al as a}from"./chunks/framework.BawR2jEz.js";const p=JSON.parse('{"title":"Контекстные методы","description":"Методы, доступные внутри шаблонов блоков, рубрик и сущностей — fld, fld_list, component, preset_fld.","frontmatter":{"title":"Контекстные методы","description":"Методы, доступные внутри шаблонов блоков, рубрик и сущностей — fld, fld_list, component, preset_fld."},"headers":[],"relativePath":"editor/template/methods/index.md","filePath":"editor/template/methods/index.md"}'),r={name:"editor/template/methods/index.md"};function l(c,t,i,n,h,s){return d(),o("div",null,[...t[0]||(t[0]=[a('<div><h1 id="контекстные-методы" tabindex="-1">Контекстные методы <a class="header-anchor" href="#контекстные-методы" aria-label="Permalink to &quot;Контекстные методы&quot;">​</a></h1><p>Методы, доступные напрямую — без префикса <code>ex.</code> — внутри шаблона сущности: блока, документа, категории, коллекции, товара, рубрики и превью.</p><p>В отличие от <a href="./../functions/">глобальных функций</a>, контекстный метод знает, в шаблоне какой сущности он вызван, поэтому идентификатор сущности указывать не нужно.</p><h2 id="методы" tabindex="-1">Методы <a class="header-anchor" href="#методы" aria-label="Permalink to &quot;Методы&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Метод</th><th>Возвращает</th><th>Описание</th></tr></thead><tbody><tr><td><a href="./fld.html">fld()</a></td><td><code>string</code></td><td>HTML поля текущей сущности по хэштегу</td></tr><tr><td><a href="./fld_list.html">fld_list()</a></td><td><code>array</code></td><td>Все поля блока указанного типа: хэштег → HTML</td></tr><tr><td><a href="./component.html">component()</a></td><td><code>string</code></td><td>HTML компонента текущей сущности</td></tr><tr><td><a href="./preset_fld.html">preset_fld()</a></td><td><code>string</code></td><td>HTML пресет-поля</td></tr></tbody></table><h2 id="где-какои-метод-доступен" tabindex="-1">Где какой метод доступен <a class="header-anchor" href="#где-какои-метод-доступен" aria-label="Permalink to &quot;Где какой метод доступен&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Шаблон</th><th>Доступные методы</th></tr></thead><tbody><tr><td>Блок</td><td><code>fld()</code>, <code>fld_list()</code>, <code>component()</code></td></tr><tr><td>Рубрика — страница документа, категории, коллекции, товара</td><td><code>fld()</code>, <code>component()</code>, <code>preset_fld()</code></td></tr><tr><td>Превью рубрики</td><td><code>fld()</code>, <code>component()</code></td></tr><tr><td>Описание товара и категории OpenCart</td><td><code>preset_fld()</code></td></tr><tr><td>Значение полей «Строка» и «Текст»</td><td><code>preset_fld()</code></td></tr></tbody></table><p>В шаблонах рубрики и превью метод <code>fld()</code> вызывается у сущности, для которой идёт рендер, — документа, категории, коллекции или товара.</p><h2 id="если-метод-не-наиден" tabindex="-1">Если метод не найден <a class="header-anchor" href="#если-метод-не-наиден" aria-label="Permalink to &quot;Если метод не найден&quot;">​</a></h2><p>Опечатка в имени метода не роняет страницу и не пишет ничего в лог — вместо результата на витрине появляется красная плашка:</p><blockquote><p>Функция: fdl не существует. Аргументы: [...]</p></blockquote><p>Значит имя не нашлось ни среди методов сущности, ни среди методов её контекста. Обычные причины — опечатка либо вызов метода в шаблоне, где он недоступен: сверьтесь с таблицей выше.</p><p>Плашку видит любой посетитель, поэтому проверяйте шаблон после правок.</p><h2 id="см-также" tabindex="-1">См. также <a class="header-anchor" href="#см-также" aria-label="Permalink to &quot;См. также&quot;">​</a></h2><ul><li><a href="./../functions/">Функции Twig exDoc</a> — глобальные функции объекта <code>ex</code></li><li><a href="./../oc/">Объект oc</a> — доступ к настройкам, документу, запросу и моделям OpenCart</li><li><a href="./../filters/">Фильтры Twig exDoc</a> — обработка текста, чисел, дат и массивов</li><li><a href="./../../../blocks/twig-methods.html">Контекстные методы блоков</a> — свойства, доступные в шаблоне блока</li><li><a href="./../../../rubrics/exdoc-document/context.html">Объекты в шаблонах рубрик</a> — свойства документа, категории, товара</li></ul></div>',1)])])}const m=e(r,[["render",l]]);export{p as __pageData,m as default};
